type TripInfo={index:number;total:number;clusterKey:string};

function tripSignature(purchase:QuarryPurchase){const transportKey=purchase.deliveryMethod==='supplier'?`supplier:${purchase.truckPlate.trim().toLocaleLowerCase('en-US')}`:`company:${purchase.driverId}:${purchase.truckId}`;return[localDate(purchase.confirmedAt),purchase.itemId,purchase.unitId,transportKey].join('|');}
function computeTripInfo(purchases:QuarryPurchase[]):Map<string,TripInfo>{
  const clusters=new Map<string,QuarryPurchase[]>();
  for(const purchase of purchases){const key=tripSignature(purchase);const list=clusters.get(key);if(list)list.push(purchase);else clusters.set(key,[purchase]);}
  const info=new Map<string,TripInfo>();
  for(const[key,members]of clusters){if(members.length<2)continue;const ordered=[...members].sort((a,b)=>a.confirmedAt.localeCompare(b.confirmedAt));ordered.forEach((purchase,index)=>info.set(purchase.id,{index:index+1,total:ordered.length,clusterKey:key}));}
  return info;
}
function matchesSearch(purchase:QuarryPurchase,query:string){const haystack=[purchase.supplierName,purchaseDestinationName(purchase)??'',purchase.itemName,purchase.purchaseNumber,purchase.supplierTicketNumber??'',purchase.driverName,purchase.truckPlate].join(' ').toLocaleLowerCase('en-US');return haystack.includes(query);}

