        <View style={styles.groupCopy}><Text style={styles.groupEyebrow}>DELIVERY SUMMARY</Text><Text style={styles.summaryTitle}>Delivered material totals</Text><Text style={styles.summaryHint}>Every active confirmed delivery. Not affected by the search and date filters below.</Text></View>
